/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for the TSIG K* (KegQtyUOM) calculation
/// </summary>
internal final class METTMSShipmentItemGroupUOM_Default extends METTMSShipmentItemGroupUOM
{
}

Method.Source:
/// <summary>
/// Method for the TSIG quantity UOM
/// </summary>
/// <returns>Shipment UOM K* where * is a number e.g. K20, K195</returns>
METShipmentUOM shipmentUOM()
{
    return lineTmpSum.KegQtyUOM;
}

/// <summary>
/// Method to calculate TSIG volume (cube)
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG volume (cube)</returns>
METWHSPalletVolume cube(METQty _quantity)
{
    return lineTmpSum.LineVolume_Kegs;
}

/// <summary>
/// Method to calculate TSIG quantity
/// </summary>
/// <returns>TSIG quantity</returns>
METQty quantity()
{
    return lineTmpSum.SalesQty;
}

/// <summary>
/// Method to calculate TSIG weight
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG weight</returns>
METWHSPalletWeight weight(METQty _quantity)
{
    return lineTmpSum.LineWeight_Kegs;
}
